import { Controller, Get, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const USE_YN = ['사용', '미사용'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function checkTypeName(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw invalid('근태항목명을 입력해 주세요.');
  }
  if (value.length > 100) {
    throw invalid('근태항목명은 100자 이하로 입력해 주세요.');
  }
  return value;
}

function checkUseYn(value: unknown): string {
  if (typeof value !== 'string' || !USE_YN.includes(value)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return value;
}

function checkDescription(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw invalid('설명은 글자로 입력해 주세요.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01702Controller {
  @Get('/attendance-types')
  async listAttendanceTypes(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const q = checks.queryOf(req.query);
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const size = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(page) || page < 0) {
      throw invalid('page는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw invalid('size는 1 이상의 정수여야 합니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const useYnRaw = q['useYn'];
    const hasUseYn = useYnRaw !== undefined && useYnRaw !== '';
    if (hasUseYn) {
      checkUseYn(useYnRaw);
    }
    return transaction(async (db) => {
      const where = hasUseYn ? 'WHERE use_yn = :useYn' : '';
      const params: Record<string, unknown> = { limit, offset: page * limit };
      if (hasUseYn) {
        params['useYn'] = useYnRaw;
      }
      const items = await db.query(
        'SELECT attendance_type_id AS "attendanceTypeId", type_name AS "typeName", description AS "description", use_yn AS "useYn" ' +
          'FROM attendance_type ' + where + ' ORDER BY attendance_type_id LIMIT :limit OFFSET :offset',
        params,
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM attendance_type ' + where,
        hasUseYn ? { useYn: useYnRaw } : {},
      );
      return { items, page, size: limit, total: Number(counted[0]['total']) };
    });
  }

  @Post('/attendance-types')
  @HttpCode(200)
  async createAttendanceType(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const typeName = checkTypeName(data['typeName']);
    const useYn = checkUseYn(data['useYn']);
    const description = checkDescription(data['description']);
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT attendance_type_id FROM attendance_type WHERE type_name = :typeName',
        { typeName },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ATTENDANCE_TYPE_NAME_DUPLICATED', '이미 등록된 근태항목명입니다.');
      }
      const rows = await db.query(
        'INSERT INTO attendance_type (type_name, description, use_yn, created_at, updated_at) ' +
          'VALUES (:typeName, :description, :useYn, now(), now()) RETURNING attendance_type_id AS "attendanceTypeId"',
        { typeName, description, useYn },
      );
      // 가정: 변경 이력(공통 P15)은 공통 모듈이 맡는다.
      return { attendanceTypeId: Number(rows[0]['attendanceTypeId']) };
    });
  }

  @Patch('/attendance-types/:attendanceTypeId')
  async updateAttendanceType(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const idText = req.params['attendanceTypeId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw invalid('근태항목 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const typeName = data['typeName'] === undefined ? null : checkTypeName(data['typeName']);
    const useYn = data['useYn'] === undefined ? null : checkUseYn(data['useYn']);
    const hasDescription = data['description'] !== undefined;
    const description = hasDescription ? checkDescription(data['description']) : null;
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT attendance_type_id FROM attendance_type WHERE attendance_type_id = CAST(:id AS bigint)',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_TYPE_NOT_FOUND', '근태항목을 찾을 수 없습니다.');
      }
      if (typeName !== null) {
        const dup = await db.query(
          'SELECT attendance_type_id FROM attendance_type WHERE type_name = :typeName AND attendance_type_id <> CAST(:id AS bigint)',
          { typeName, id: idText },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'ATTENDANCE_TYPE_NAME_DUPLICATED', '이미 등록된 근태항목명입니다.');
        }
      }
      const rows = await db.query(
        'UPDATE attendance_type SET ' +
          'type_name = COALESCE(CAST(:typeName AS text), type_name), ' +
          'use_yn = COALESCE(CAST(:useYn AS text), use_yn), ' +
          'description = CASE WHEN CAST(:hasDescription AS boolean) THEN CAST(:description AS text) ELSE description END, ' +
          'updated_at = now() ' +
          'WHERE attendance_type_id = CAST(:id AS bigint) RETURNING attendance_type_id AS "attendanceTypeId"',
        { typeName, useYn, hasDescription, description, id: idText },
      );
      // 가정: 변경 이력(공통 P15)은 공통 모듈이 맡는다.
      return { attendanceTypeId: Number(rows[0]['attendanceTypeId']) };
    });
  }
}

