import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const USE_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

type Mode = { kind: 'create' } | { kind: 'edit'; row: Row } | null;

export default function FnSfr01702Page({ role, notify }: PageProps) {
  const [useYn, setUseYn] = useState('');
  const [filterUseYn, setFilterUseYn] = useState('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-types', role, undefined, { useYn: filterUseYn, page, size: SIZE }),
    [role, filterUseYn, page],
  );
  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 근태항목</h2>
        <Num value={total} />
      </section>
      <section className="box span-8">
        <h2>근태항목</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setFilterUseYn(useYn);
          }}
          onReset={() => {
            setUseYn('');
            setFilterUseYn('');
            setPage(0);
          }}
        >
          <Field label="사용 여부">
            <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={() => setMode({ kind: 'create' })}>
            근태항목 등록
          </button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty="등록된 근태항목이 없습니다."
          columns={[
            { key: 'typeName', label: '근태항목명' },
            { key: 'description', label: '설명' },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
            {
              key: 'attendanceTypeId',
              label: '처리',
              render: (r) => (
                <button type="button" onClick={() => setMode({ kind: 'edit', row: r })}>
                  수정
                </button>
              ),
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      {mode && mode.kind === 'create' ? (
        <Drawer title="근태항목 등록" onClose={() => setMode(null)}>
          <TypeForm
            role={role}
            submitLabel="등록"
            onDone={() => {
              setMode(null);
              notify('근태항목을 등록했습니다.');
              reload();
            }}
          />
        </Drawer>
      ) : null}
      {mode && mode.kind === 'edit' ? (
        <Drawer title="근태항목 수정" onClose={() => setMode(null)}>
          <TypeForm
            role={role}
            submitLabel="저장"
            row={mode.row}
            onDone={() => {
              setMode(null);
              notify('근태항목을 수정했습니다.');
              reload();
            }}
          />
        </Drawer>
      ) : null}
    </div>
  );
}

function TypeForm({
  role,
  row,
  submitLabel,
  onDone,
}: {
  role: string;
  row?: Row;
  submitLabel: string;
  onDone: () => void;
}) {
  const [typeName, setTypeName] = useState(row ? String(row['typeName'] ?? '') : '');
  const [description, setDescription] = useState(row ? String(row['description'] ?? '') : '');
  const [useYn, setUseYn] = useState(row ? String(row['useYn'] ?? '') : '사용');

  const submit = async () => {
    if (typeName.trim() === '') {
      throw new Error('근태항목명을 입력해 주세요.');
    }
    if (useYn === '') {
      throw new Error('사용 여부를 선택해 주세요.');
    }
    const body: Row = { typeName, description, useYn };
    if (row) {
      await call('PATCH', '/attendance-types/' + String(row['attendanceTypeId']), role, body);
    } else {
      await call('POST', '/attendance-types', role, body);
    }
    onDone();
  };

  return (
    <Form onSubmit={submit} submit={submitLabel}>
      <Field label="근태항목명" required>
        <TextInput value={typeName} onChange={setTypeName} />
      </Field>
      <Field label="설명" wide>
        <TextInput value={description} onChange={setDescription} multiline />
      </Field>
      <Field label="사용 여부" required>
        <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} />
      </Field>
    </Form>
  );
}
